node -e "
const db = require('better-sqlite3')('/workspace/world.db', {readonly: true});
// First find the product
const products = db.prepare(\"SELECT * FROM products WHERE name LIKE '%Wireless Mouse%' OR name LIKE '%LogiTech%' OR name LIKE '%M310%'\").all();
console.log('=== PRODUCTS ===');
console.log(JSON.stringify(products, null, 2));

// Get variants for each product
for (const p of products) {
  const variants = db.prepare('SELECT * FROM rt_variants WHERE product_id = ?').all(p.product_id);
  console.log('\n=== VARIANTS for', p.name, '(product_id:', p.product_id, ') ===');
  console.log(JSON.stringify(variants, null, 2));
}
db.close();
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db', {readonly: true});

// Check if there's also a tau2Retail-scoped product
const tau2Products = db.prepare(\"SELECT * FROM products WHERE source_skill='tau2Retail' AND (name LIKE '%Mouse%' OR name LIKE '%LogiTech%')\").all();
console.log('=== tau2Retail Products ===');
console.log(JSON.stringify(tau2Products, null, 2));

// Also check compatible products
const compat = ['PROD-B98D14','PROD-2DBA15','PROD-73FAB4'];
for (const pid of compat) {
  const p = db.prepare('SELECT product_id, name, brand, category FROM products WHERE product_id = ?').get(pid);
  console.log('Compatible:', JSON.stringify(p));
}

// Check the specs and description more carefully
const main = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-FA0948'\").get();
console.log('\n=== Full Product Record ===');
console.log(JSON.stringify(main, null, 2));

// Check if there are variants in a different table or with different product_id format
const allVariants = db.prepare(\"SELECT * FROM rt_variants WHERE product_id LIKE '%FA0948%'\").all();
console.log('\n=== rt_variants search ===');
console.log(JSON.stringify(allVariants, null, 2));

// Check if variants_json has anything in other products for reference
const sampleVariants = db.prepare(\"SELECT product_id, name, variants_json FROM products WHERE variants_json != '[]' LIMIT 3\").all();
console.log('\n=== Products with non-empty variants_json ===');
console.log(JSON.stringify(sampleVariants, null, 2));

db.close();
"
